-- 4. MAXIMUS — [M1 | automate_dv.ma_sat] SAT_PARTY_ORG_DIRECTORS   [Implemented]
-- HASHDIFF column HASHDIFF_PARTY_ORG_DIRECTORS. Recomputed exactly as automate_dv 0.11.5
-- / sat_multi_source computes it, from the payload stored on the same row. A match
-- proves every payload change changes the HASHDIFF, which is what drives a new row.
-- standard satellite, automate_dv.ma_sat; PK PARTY_HKEY, child key PERSONROLE; 1
-- RECORD_SOURCE group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [3 col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME
-- per member.
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_PARTY_ORG_DIRECTORS' as satellite, 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF_PARTY_ORG_DIRECTORS is null) as null_hashdiff,
       count_if(HASHDIFF_PARTY_ORG_DIRECTORS <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(CESSATIONDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DIRECTORNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PERSONROLE AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF_PARTY_ORG_DIRECTORS <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(CESSATIONDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DIRECTORNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PERSONROLE AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORG_DIRECTORS
 where (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORG_DIRECTORS where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_ORG_DIRECTORS' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#1
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('AUTHORISED_SIGNATORY') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               cast(null as varchar) as CESSATIONDATE,
               to_varchar((nullif(trim(to_varchar("AUTHORIZED_SIGNATURE")), ''))) as DIRECTORNAME,
               to_varchar('AUTHORISED_SIGNATORY') as PERSONROLE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("AUTHORIZED_SIGNATURE")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#2
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('EMPLOYEE') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               cast(null as varchar) as CESSATIONDATE,
               to_varchar((nullif(trim(to_varchar("NAME_OF_THE_EMPLOYEE")), ''))) as DIRECTORNAME,
               to_varchar('EMPLOYEE') as PERSONROLE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("NAME_OF_THE_EMPLOYEE")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#3
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('HEAD_FRAUD_PREVENTION_LOSS_MITIGATION') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               cast(null as varchar) as CESSATIONDATE,
               to_varchar((nullif(trim(to_varchar("NAME_OF_THE_HEAD_FRAUD_PREVENTION_AND_LOSS_MITIGATION")), ''))) as DIRECTORNAME,
               to_varchar('HEAD_FRAUD_PREVENTION_LOSS_MITIGATION') as PERSONROLE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("NAME_OF_THE_HEAD_FRAUD_PREVENTION_AND_LOSS_MITIGATION")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#4
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('INVESTIGATION_OFFICER') as cdk_1,
