----------------------------------------------------------------------------------------
-- 8. MAXIMUS — [M1 | ma_sat_multi_source] SAT_PARTY_DIGITAL_IDENTITY   [Implemented]
-- HASHDIFF column HASHDIFF_PARTY_DIGITAL_IDENTITY. Recomputed exactly as automate_dv
-- 0.11.5 / sat_multi_source computes it, from the payload stored on the same row. A
-- match proves every payload change changes the HASHDIFF, which is what drives a new
-- row. standard satellite, ma_sat_multi_source; PK PARTY_HKEY, child key
-- ACTIVESEQUENCENUMBER; 2 RECORD_SOURCE group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [0 col(s)],
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [1 col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME
-- per member.
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_PARTY_DIGITAL_IDENTITY' as satellite, '2 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF_PARTY_DIGITAL_IDENTITY is null) as null_hashdiff,
       count_if(HASHDIFF_PARTY_DIGITAL_IDENTITY <> CAST(MD5_BINARY(IFNULL(NULLIF(UPPER(TRIM(CAST(LOGINIDENTIFIER AS VARCHAR))), ''), '^^')) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF_PARTY_DIGITAL_IDENTITY <> CAST(MD5_BINARY(IFNULL(NULLIF(UPPER(TRIM(CAST(LOGINIDENTIFIER AS VARCHAR))), ''), '^^')) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_DIGITAL_IDENTITY
 where (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s2 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_DIGITAL_IDENTITY where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_DIGITAL_IDENTITY' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via unpivot_mp__pd_prop_sp_pv__party_digital_identity#1
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('PORTAL_LOGIN') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar((nullif(trim(to_varchar("LOGIN_ID")), ''))) as LOGINIDENTIFIER
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("LOGIN_ID")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_digital_identity#2
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('REPAIRER_PORTAL') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar((nullif(trim(to_varchar("REPAIRER_PORTAL_ID")), ''))) as LOGINIDENTIFIER
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("REPAIRER_PORTAL_ID")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_digital_identity#3
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('SURVEYOR_MODULE') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar((nullif(trim(to_varchar("SUR_MODULE_LOGIN_ID")), ''))) as LOGINIDENTIFIER
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("SUR_MODULE_LOGIN_ID")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_digital_identity#4
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('USER_CODE') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar((nullif(trim(to_varchar("USER_CODE")), ''))) as LOGINIDENTIFIER
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("USER_CODE")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_digital_identity#5
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('WEB_PORTAL') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar((nullif(trim(to_varchar("USER_WEB_ID")), ''))) as LOGINIDENTIFIER
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("USER_WEB_ID")), '')))), '') is not null
      )
     where hkey in (select hkey from s2) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1 order by ldts desc) = 1
),
n2 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, coalesce(to_varchar(ACTIVESEQUENCENUMBER), '^^') as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_DIGITAL_IDENTITY
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' and PARTY_HKEY in (select hkey from s2)
     group by 1, 2
),
x2 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, coalesce(e.cdk_1, '^^') as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.LOGINIDENTIFIER AS VARCHAR))), ''), '^^'))) as raw_hash
      from e2 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_PARTY_DIGITAL_IDENTITY', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n2 n full outer join x2 x on x.hkey = n.hkey and x.cdk = n.cdk;



----------------------------------------------------------------------------------------
-- 9. MAXIMUS — [M1 | sat_multi_source] SAT_COMMON_ADDRESS   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- sat_multi_source; PK LOCATION_HKEY; 3 RECORD_SOURCE group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS [8 col(s)],
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW
-- [6 col(s)],
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [9 col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_COMMON_ADDRESS' as satellite, '3 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ADDRESSLINE1 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ADDRESSLINE2 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ADDRESSLINE3 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CAREOFNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(COUNTRYNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DISTRICT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LANDMARK AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LOCALITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POSTALCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POSTOFFICENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(STATENAME AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ADDRESSLINE1 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ADDRESSLINE2 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ADDRESSLINE3 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CAREOFNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(COUNTRYNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DISTRICT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LANDMARK AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LOCALITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POSTALCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POSTOFFICENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(STATENAME AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(LOCATION_HKEY, 'HEX'), null)) within group (order by LOCATION_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS
 where (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS') or (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct LOCATION_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_COMMON_ADDRESS' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_addr
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (case when coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("ADDRESS1")), ''))))), upper(trim(to_varchar((nullif(trim(to_varchar("ADDRESS2")), ''))))), upper(trim(to_varchar((nullif(trim(to_varchar("ADDRESS3")), ''))))), upper(trim(to_varchar(((nullif(trim(to_varchar("CITY")), '')))))), upper(trim(to_varchar(((nullif(trim(to_varchar("DISTRICT")), '')))))), upper(trim(to_varchar((nullif(trim(to_varchar("STATE")), ''))))), upper(trim(to_varchar((nullif(trim(to_varchar("PINCODE")), ''))))), upper(trim(to_varchar((nullif(trim(to_varchar("COUNTRY")), '')))))) is null then null else md5(concat_ws('|', coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("ADDRESS1")), ''))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("ADDRESS2")), ''))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("ADDRESS3")), ''))))), ''), coalesce(upper(trim(to_varchar(((nullif(trim(to_varchar("CITY")), '')))))), ''), coalesce(upper(trim(to_varchar(((nullif(trim(to_varchar("DISTRICT")), '')))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("STATE")), ''))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("PINCODE")), ''))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("COUNTRY")), ''))))), ''))) end) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("ADDRESS1")), ''))) as ADDRESSLINE1,
               to_varchar((nullif(trim(to_varchar("ADDRESS2")), ''))) as ADDRESSLINE2,
               to_varchar((nullif(trim(to_varchar("ADDRESS3")), ''))) as ADDRESSLINE3,
               to_varchar((nullif(trim(to_varchar("CITY")), ''))) as CITY,
               to_varchar((nullif(trim(to_varchar("COUNTRY")), ''))) as COUNTRYNAME,
               to_varchar((nullif(trim(to_varchar("DISTRICT")), ''))) as DISTRICT,
               to_varchar((nullif(trim(to_varchar("PINCODE")), ''))) as POSTALCODE,
               to_varchar((nullif(trim(to_varchar("STATE")), ''))) as STATENAME
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select LOCATION_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS' and LOCATION_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.ADDRESSLINE1 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.ADDRESSLINE2 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.ADDRESSLINE3 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.COUNTRYNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.DISTRICT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POSTALCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.STATENAME AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_COMMON_ADDRESS', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

