-- 10. MAXIMUS — [M1 | sat_multi_source] SAT_LOCATION_PROFILE   [Implemented]
-- HASHDIFF column HASHDIFF_LOCATION_PROFILE. Recomputed exactly as automate_dv 0.11.5 /
-- sat_multi_source computes it, from the payload stored on the same row. A match proves
-- every payload change changes the HASHDIFF, which is what drives a new row. standard
-- satellite, sat_multi_source; PK LOCATION_HKEY; 2 RECORD_SOURCE group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW
-- [1 col(s)],
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [1 col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_LOCATION_PROFILE' as satellite, '2 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
