----------------------------------------------------------------------------------------
-- 14. MAXIMUS — [M1 | sat_multi_source(OBJECT)] SAT_PARTY_IDENTIFICATION   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- sat_multi_source; PK PARTY_HKEY; 2 RECORD_SOURCE group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [3 col(s)],
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [27 col(s)]. OBJECT satellite: AADHAARNUMBER, GSTIN, PANNUMBER, PASSPORTNUMBER,
-- VOTERIDNUMBER, CKYCNUMBER hold one entry per source table (sat value = col:"<TABLE>";
-- expected = MAX over that table's RAW rows, as the macro does). Plain columns are MAX
-- across all tables and are not compared per table. A table absent from the latest
-- incremental window is absent from the latest row -- compare after a full load.
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_PARTY_IDENTIFICATION' as satellite, 'all MAXIMUS rows (OBJECT hashdiff)' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT(IFNULL(TO_JSON(AADHAARNUMBER), '^^'), '||', IFNULL(TO_JSON(GSTIN), '^^'), '||', IFNULL(TO_JSON(PANNUMBER), '^^'), '||', IFNULL(TO_JSON(PASSPORTNUMBER), '^^'), '||', IFNULL(TO_JSON(VOTERIDNUMBER), '^^'), '||', IFNULL(TO_JSON(CKYCNUMBER), '^^'), '||', IFNULL(CAST(AADHAARVERIFICATIONSTATUS AS VARCHAR), '^^'), '||', IFNULL(CAST(AGEPROOFTYPE AS VARCHAR), '^^'), '||', IFNULL(CAST(CINNUMBER AS VARCHAR), '^^'), '||', IFNULL(CAST(DRIVINGLICENCEEXPIRYDATE AS VARCHAR), '^^'), '||', IFNULL(CAST(DRIVINGLICENCENUMBER AS VARCHAR), '^^'), '||', IFNULL(CAST(EIANUMBER AS VARCHAR), '^^'), '||', IFNULL(CAST(FORM60INDICATOR AS VARCHAR), '^^'), '||', IFNULL(CAST(GSTREGISTRATIONSTATUS AS VARCHAR), '^^'), '||', IFNULL(CAST(GSTTAXPAYERTYPE AS VARCHAR), '^^'), '||', IFNULL(CAST(IDENTIFICATIONEXPIRYDATE AS VARCHAR), '^^'), '||', IFNULL(CAST(IDENTIFICATIONISSUEDATE AS VARCHAR), '^^'), '||', IFNULL(CAST(IDENTIFICATIONISSUINGAUTHORITY AS VARCHAR), '^^'), '||', IFNULL(CAST(IDENTIFICATIONNUMBER AS VARCHAR), '^^'), '||', IFNULL(CAST(IDENTIFICATIONTYPECODE AS VARCHAR), '^^'), '||', IFNULL(CAST(IDENTIFICATIONVERIFIEDINDICATOR AS VARCHAR), '^^'), '||', IFNULL(CAST(INSURANCEREPOSITORYNAME AS VARCHAR), '^^'), '||', IFNULL(CAST(NREGACARDNUMBER AS VARCHAR), '^^'), '||', IFNULL(CAST(OVDCATEGORY AS VARCHAR), '^^'), '||', IFNULL(CAST(PANVERIFICATIONSTATUS AS VARCHAR), '^^'), '||', IFNULL(CAST(PASSPORTEXPIRYDATE AS VARCHAR), '^^'), '||', IFNULL(CAST(TANNUMBER AS VARCHAR), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT(IFNULL(TO_JSON(AADHAARNUMBER), '^^'), '||', IFNULL(TO_JSON(GSTIN), '^^'), '||', IFNULL(TO_JSON(PANNUMBER), '^^'), '||', IFNULL(TO_JSON(PASSPORTNUMBER), '^^'), '||', IFNULL(TO_JSON(VOTERIDNUMBER), '^^'), '||', IFNULL(TO_JSON(CKYCNUMBER), '^^'), '||', IFNULL(CAST(AADHAARVERIFICATIONSTATUS AS VARCHAR), '^^'), '||', IFNULL(CAST(AGEPROOFTYPE AS VARCHAR), '^^'), '||', IFNULL(CAST(CINNUMBER AS VARCHAR), '^^'), '||', IFNULL(CAST(DRIVINGLICENCEEXPIRYDATE AS VARCHAR), '^^'), '||', IFNULL(CAST(DRIVINGLICENCENUMBER AS VARCHAR), '^^'), '||', IFNULL(CAST(EIANUMBER AS VARCHAR), '^^'), '||', IFNULL(CAST(FORM60INDICATOR AS VARCHAR), '^^'), '||', IFNULL(CAST(GSTREGISTRATIONSTATUS AS VARCHAR), '^^'), '||', IFNULL(CAST(GSTTAXPAYERTYPE AS VARCHAR), '^^'), '||', IFNULL(CAST(IDENTIFICATIONEXPIRYDATE AS VARCHAR), '^^'), '||', IFNULL(CAST(IDENTIFICATIONISSUEDATE AS VARCHAR), '^^'), '||', IFNULL(CAST(IDENTIFICATIONISSUINGAUTHORITY AS VARCHAR), '^^'), '||', IFNULL(CAST(IDENTIFICATIONNUMBER AS VARCHAR), '^^'), '||', IFNULL(CAST(IDENTIFICATIONTYPECODE AS VARCHAR), '^^'), '||', IFNULL(CAST(IDENTIFICATIONVERIFIEDINDICATOR AS VARCHAR), '^^'), '||', IFNULL(CAST(INSURANCEREPOSITORYNAME AS VARCHAR), '^^'), '||', IFNULL(CAST(NREGACARDNUMBER AS VARCHAR), '^^'), '||', IFNULL(CAST(OVDCATEGORY AS VARCHAR), '^^'), '||', IFNULL(CAST(PANVERIFICATIONSTATUS AS VARCHAR), '^^'), '||', IFNULL(CAST(PASSPORTEXPIRYDATE AS VARCHAR), '^^'), '||', IFNULL(CAST(TANNUMBER AS VARCHAR), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION
 where RECORD_SOURCE = 'MAXIMUS';

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION where RECORD_SOURCE = 'MAXIMUS' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_IDENTIFICATION' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select hkey, max(PASSPORTNUMBER) as PASSPORTNUMBER
      from (
        -- via stg_maximus__pd_prop_msdp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("PASSPORT_NUMBER")), ''))) as PASSPORTNUMBER
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
     group by hkey
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION
     where RECORD_SOURCE = 'MAXIMUS' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.PASSPORTNUMBER AS VARCHAR))), ''), '^^'))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_PARTY_IDENTIFICATION', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s2 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION where RECORD_SOURCE = 'MAXIMUS' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_IDENTIFICATION' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select hkey, max(AADHAARNUMBER) as AADHAARNUMBER, max(CKYCNUMBER) as CKYCNUMBER, max(GSTIN) as GSTIN, max(PANNUMBER) as PANNUMBER, max(PASSPORTNUMBER) as PASSPORTNUMBER, max(VOTERIDNUMBER) as VOTERIDNUMBER
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("AADHAAR_NUMBER")), ''))) as AADHAARNUMBER,
               to_varchar((nullif(trim(to_varchar("CKYC_NUMBER")), ''))) as CKYCNUMBER,
               to_varchar((nullif(trim(to_varchar("GSTINUIN")), ''))) as GSTIN,
               to_varchar((nullif(trim(to_varchar("PAN_NO")), ''))) as PANNUMBER,
               to_varchar((nullif(trim(to_varchar("PASSPORT_NUMBER")), ''))) as PASSPORTNUMBER,
               to_varchar((nullif(trim(to_varchar("VOTER_ID")), ''))) as VOTERIDNUMBER
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s2) and ldts is not null
     group by hkey
),
n2 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION
     where RECORD_SOURCE = 'MAXIMUS' and PARTY_HKEY in (select hkey from s2)
     group by 1, 2
),
x2 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.AADHAARNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CKYCNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.GSTIN AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PANNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PASSPORTNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.VOTERIDNUMBER AS VARCHAR))), ''), '^^')))) as raw_hash
      from e2 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_PARTY_IDENTIFICATION', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n2 n full outer join x2 x on x.hkey = n.hkey and x.cdk = n.cdk;



