-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- sat_multi_source; PK PARTY_HKEY; 2 RECORD_SOURCE group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL [3 col(s)],
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [13 col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_PARTY_ORGANISATION_PROFILE' as satellite, '2 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ANNUALTURNOVER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(BUSINESSREGISTRATIONNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DATEOFINCORPORATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(GROUPNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INDUSTRYCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INDUSTRYDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LEGALCONSTITUTIONTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MSMECATEGORY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MSMEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NATUREOFBUSINESS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NUMBEROFEMPLOYEES AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PAIDUPCAPITAL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARENTENTITYNAME AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ANNUALTURNOVER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(BUSINESSREGISTRATIONNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DATEOFINCORPORATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(GROUPNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INDUSTRYCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INDUSTRYDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LEGALCONSTITUTIONTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MSMECATEGORY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MSMEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NATUREOFBUSINESS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NUMBEROFEMPLOYEES AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PAIDUPCAPITAL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARENTENTITYNAME AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORGANISATION_PROFILE
 where (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL') or (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORGANISATION_PROFILE where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_ORGANISATION_PROFILE' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("PARTY_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("REGISTRATION_NO")), ''))) as BUSINESSREGISTRATIONNUMBER,
               to_varchar((nullif(trim(to_varchar("REGISTRATION_DATE")), ''))) as DATEOFINCORPORATION,
               to_varchar((nullif(trim(to_varchar("TYPE_OF_ORGANIZATION")), ''))) as LEGALCONSTITUTIONTYPE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORGANISATION_PROFILE
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.BUSINESSREGISTRATIONNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.DATEOFINCORPORATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.LEGALCONSTITUTIONTYPE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_PARTY_ORGANISATION_PROFILE', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s2 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORGANISATION_PROFILE where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_ORGANISATION_PROFILE' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("ANNUAL_TURNOVER")), ''))) as ANNUALTURNOVER,
               to_varchar((nullif(trim(to_varchar("COMPANY_NO")), ''))) as BUSINESSREGISTRATIONNUMBER,
               to_varchar((nullif(trim(to_varchar("DATE_OF_REGISTRATION_OR_INCORPORATION")), ''))) as DATEOFINCORPORATION,
               to_varchar((nullif(trim(to_varchar("GLOBAL_CO_NAME")), ''))) as GROUPNAME,
               to_varchar((nullif(trim(to_varchar("INDUSTRY_CODE")), ''))) as INDUSTRYCODE,
               to_varchar((nullif(trim(to_varchar("INDUSTRY_TYPE")), ''))) as INDUSTRYDESCRIPTION,
               to_varchar((nullif(trim(to_varchar("LEGAL_CONSTITUTION")), ''))) as LEGALCONSTITUTIONTYPE,
               to_varchar((nullif(trim(to_varchar("MSME_CLASSIFICATION")), ''))) as MSMECATEGORY,
               to_varchar((nullif(trim(to_varchar("MSME_APPLICABLE")), ''))) as MSMEINDICATOR,
               to_varchar((nullif(trim(to_varchar("BUSINESS_TYPE")), ''))) as NATUREOFBUSINESS,
               to_varchar((nullif(trim(to_varchar("STAFF_STRENGTH_TOTAL")), ''))) as NUMBEROFEMPLOYEES,
               to_varchar((nullif(trim(to_varchar("PAID_UP_CAPITAL")), ''))) as PAIDUPCAPITAL,
               to_varchar((nullif(trim(to_varchar("PARENT_CO")), ''))) as PARENTENTITYNAME
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s2) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n2 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORGANISATION_PROFILE
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' and PARTY_HKEY in (select hkey from s2)
     group by 1, 2
),
x2 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.ANNUALTURNOVER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.BUSINESSREGISTRATIONNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.DATEOFINCORPORATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.GROUPNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.INDUSTRYCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.INDUSTRYDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.LEGALCONSTITUTIONTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.MSMECATEGORY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.MSMEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.NATUREOFBUSINESS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.NUMBEROFEMPLOYEES AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PAIDUPCAPITAL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PARENTENTITYNAME AS VARCHAR))), ''), '^^')))) as raw_hash
      from e2 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_PARTY_ORGANISATION_PROFILE', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n2 n full outer join x2 x on x.hkey = n.hkey and x.cdk = n.cdk;



