----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_PARTY_HIERARCHY' as satellite, '2 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF_PARTY_HIERARCHY is null) as null_hashdiff,
       count_if(HASHDIFF_PARTY_HIERARCHY <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(HIERARCHYLEVEL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(REPORTINGPARENTREFERENCE AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF_PARTY_HIERARCHY <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(HIERARCHYLEVEL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(REPORTINGPARENTREFERENCE AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_HIERARCHY
 where (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL') or (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW');

